    enonce: "بيّن أنّ a مقلوب b",
    correction: [{"quoi":"نكتب الجداء","math":"<span dir=\"ltr\" class=\"expr\">a × b = (1 + <span class=\"rad\"><span class=\"rcd\">2</span></span>)(<span class=\"rad\"><span class=\"rcd\">2</span></span> - 1)</span>"},{"quoi":"نستعمل المتطابقة","math":"<span dir=\"ltr\" class=\"expr\">(1 + <span class=\"rad\"><span class=\"rcd\">2</span></span>)(<span class=\"rad\"><span class=\"rcd\">2</span></span> - 1) = (<span class=\"rad\"><span class=\"rcd\">2</span></span>)<sup>2</sup> - 1<sup>2</sup></span>"},{"quoi":"نحسب المربّعين","math":"<span dir=\"ltr\" class=\"expr\">(<span class=\"rad\"><span class=\"rcd\">2</span></span>)<sup>2</sup> - 1<sup>2</sup> = 2 - 1</span>"},{"quoi":"نستنتج","math":"<span dir=\"ltr\" class=\"expr\">2 - 1 = 1</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">a × b = 1</span>، إذن a مقلوب b"}],
