    correction: [{"quoi":"ننشر الجداء الأوّل","math":"<span dir=\"ltr\" class=\"expr\"><span class=\"rad\"><span class=\"rcd\">2</span></span>(4 - 2<span class=\"rad\"><span class=\"rcd\">3</span></span>) = 4<span class=\"rad\"><span class=\"rcd\">2</span></span> - 2<span class=\"rad\"><span class=\"rcd\">6</span></span></span>"},{"quoi":"ننشر الجداء الثاني","math":"<span dir=\"ltr\" class=\"expr\">4(<span class=\"rad\"><span class=\"rcd\">2</span></span> - 1) = 4<span class=\"rad\"><span class=\"rcd\">2</span></span> - 4</span>"},{"quoi":"نطرح فيتلاشى <span dir=\"ltr\" class=\"expr\"><span class=\"rad\"><span class=\"rcd\">2</span></span></span>","math":"<span dir=\"ltr\" class=\"expr\">4<span class=\"rad\"><span class=\"rcd\">2</span></span> - 2<span class=\"rad\"><span class=\"rcd\">6</span></span> - (4<span class=\"rad\"><span class=\"rcd\">2</span></span> - 4) = 4 - 2<span class=\"rad\"><span class=\"rcd\">6</span></span></span>"},{"quoi":"نضيف الثابت","math":"<span dir=\"ltr\" class=\"expr\">1 + 4 - 2<span class=\"rad\"><span class=\"rcd\">6</span></span> = 5 - 2<span class=\"rad\"><span class=\"rcd\">6</span></span></span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">a = 5 - 2<span class=\"rad\"><span class=\"rcd\">6</span></span></span>"}],
