    correction: [{"quoi":"نبسّط جذور B","math":"<span dir=\"ltr\" class=\"expr\"><span class=\"rad\"><span class=\"rcd\">49</span></span> = 7</span>"},{"quoi":"نبسّط الجذرين الآخرين","math":"<span dir=\"ltr\" class=\"expr\"><span class=\"rad\"><span class=\"rcd\">48</span></span> - <span class=\"rad\"><span class=\"rcd\">192</span></span> = 4<span class=\"rad\"><span class=\"rcd\">3</span></span> - 8<span class=\"rad\"><span class=\"rcd\">3</span></span> = -4<span class=\"rad\"><span class=\"rcd\">3</span></span></span>"},{"quoi":"نستنتج B","math":"<span dir=\"ltr\" class=\"expr\">B = 7 - 4<span class=\"rad\"><span class=\"rcd\">3</span></span></span>"},{"quoi":"نستعمل المتطابقة","math":"<span dir=\"ltr\" class=\"expr\">A × B = (7 + 4<span class=\"rad\"><span class=\"rcd\">3</span></span>)(7 - 4<span class=\"rad\"><span class=\"rcd\">3</span></span>) = 7<sup>2</sup> - (4<span class=\"rad\"><span class=\"rcd\">3</span></span>)<sup>2</sup></span>"},{"quoi":"نحسب","math":"<span dir=\"ltr\" class=\"expr\">7<sup>2</sup> - (4<span class=\"rad\"><span class=\"rcd\">3</span></span>)<sup>2</sup> = 49 - 48 = 1</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">A × B = 1</span>، إذن <span dir=\"ltr\" class=\"expr\">A = <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">B</span></span>:</span> العددان مقلوبان"}],
