    correction: [{"quoi":"نلاحظ العلاقة بين القوسين","math":"<span dir=\"ltr\" class=\"expr\"><span class=\"rad\"><span class=\"rcd\">11</span></span> - 2 = -(2 - <span class=\"rad\"><span class=\"rcd\">11</span></span>)</span>"},{"quoi":"نغيّر إشارة الحدّ الثاني","math":"<span dir=\"ltr\" class=\"expr\">-(<span class=\"rad\"><span class=\"rcd\">11</span></span> - 2)(x - 2) = (2 - <span class=\"rad\"><span class=\"rcd\">11</span></span>)(x - 2)</span>"},{"quoi":"نضع <span dir=\"ltr\" class=\"expr\">(2 - <span class=\"rad\"><span class=\"rcd\">11</span></span>)</span> عاملا مشتركا","math":"<span dir=\"ltr\" class=\"expr\">a = (2 - <span class=\"rad\"><span class=\"rcd\">11</span></span>)[(2x - 1) + (x - 2)]</span>"},{"quoi":"نجمع ما بين المعقفين","math":"<span dir=\"ltr\" class=\"expr\">(2x - 1) + (x - 2) = 3x - 3</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">a = (2 - <span class=\"rad\"><span class=\"rcd\">11</span></span>)(3x - 3)</span>"}],
